test('normal approval resolver uses only original pending envelope and never allocates a second UUID',async()=>{const x=fixture(['sales.view']),old=x.deps.fetch;let ids=0,createBody,resolvedBody;const pricing={version:1,policyRevision:'b'.repeat(64),unitPricesExact4:[null,null],approvalId:null},draft={customerId:'2',documentDate:'2026-11-07',expectedRevision:'a'.repeat(64),items:[{productId:'8',quantityExact3:'1.000'},{productId:'1',quantityExact3:'1.000'}],discountRateExact4:'5.0000',pricing};const core=createDesktopWriteGreenCore({...x.deps,newId:()=>{ids++;return 'da171000-6f42-4f19-8cab-9f4539618647'},fetch:async(url,opts)=>{if(url.endsWith('/api/desktop-sale/discount-requests')&&opts.method==='POST'){createBody=JSON.parse(opts.body);return {ok:false,status:503,json:async()=>({success:false})};}if(url.endsWith('/api/desktop-sale/discount-requests/resolve')){resolvedBody=JSON.parse(opts.body);return {ok:true,json:async()=>({success:true,data:{state:'NOT_COMMITTED',actorId:'7',kind:resolvedBody.kind,recordId:resolvedBody.recordId,body:resolvedBody.body,summary:null}})};}return old(url,opts)}});await core.login('normal','secret');const a=core.salesApprovals();assert.equal((await a.create(draft)).state,'UNKNOWN');assert.equal((await a.resolve()).state,'NOT_COMMITTED');assert.deepEqual(resolvedBody,{kind:'create',recordId:null,body:createBody});assert.equal(a.pending(),null);assert.equal(ids,1);});
test('supplier card binds V7, both normal permissions, selected identity and live session',async()=>{const rights=['supplier.view','supplier.edit'],x=fixture(rights),original=x.deps.fetch;let version=6,foreign=false,late=false,finish;const card={id:'3',supplierCode:'S-3',name:'Ada',phone:'000',city:null,country:'',currency:'USD',purchaseDiscountRateExact4:'7.5000',isActive:true,entityId:'7',accounts:[{id:'8',supplierId:'3',entityId:'7',currency:'USD',currentBalanceExact8:'0.00000000'}]};const core=createDesktopWriteGreenCore({...x.deps,richCards:true,fetch:async(url,opts)=>{if(url.endsWith('/api/desktop-runtime'))return {ok:true,json:async()=>({success:true,data:desktopRuntimeInfo({packageSha256:'a'.repeat(64),createdAt:'2026-11-07T12:00:00.000Z',schemaVersion:version})})};if(url.endsWith('/api/desktop-suppliers/3')){if(late)await new Promise(r=>{finish=r;});return {ok:true,json:async()=>({success:true,data:foreign?{...card,id:'4'}:card})};}return original(url,opts);}});await core.login('normal','secret');await assert.rejects(core.supplierCard('3'));version=7;assert.equal((await core.supplierCard('3')).purchaseDiscountRateExact4,'7.5000');foreign=true;await assert.rejects(core.supplierCard('3'));foreign=false;late=true;const waiting=core.supplierCard('3');while(!finish)await new Promise(r=>setImmediate(r));await core.logout();finish();await assert.rejects(waiting);for(const permission of ['supplier.view','supplier.edit']){const f=fixture([permission]),c=createDesktopWriteGreenCore({...f.deps,richCards:true});await c.login('normal','secret');await assert.rejects(c.supplierCard('3'));}});
test('supplier purchase history requires all three permissions and V7, binds account and discards late logout',async()=>{const rights=['supplier.view','supplier.edit','purchase.view'],x=fixture(rights),original=x.deps.fetch;let version=6,foreign=false,finish,late=false;const data={supplierId:'2',accountId:'9',currency:'TRY',balanceExact8:'143.00000000',page:1,hasNext:false,totalCount:'0',hasUnassignedPurchases:false,lastPurchase:null,rows:[]};const core=createDesktopWriteGreenCore({...x.deps,richCards:true,fetch:async(url,opts)=>{if(url.endsWith('/api/desktop-runtime'))return{ok:true,json:async()=>({success:true,data:desktopRuntimeInfo({packageSha256:'a'.repeat(64),createdAt:'2026-11-07T12:00:00.000Z',schemaVersion:version})})};if(url.includes('/purchases?')){if(late)await new Promise(r=>finish=r);return{ok:true,json:async()=>({success:true,data:foreign?{...data,accountId:'8'}:data})};}return original(url,opts);}});await core.login('normal','secret');await assert.rejects(core.supplierPurchases('2','9',1));version=7;assert.equal((await core.supplierPurchases('2','9',1)).balanceExact8,'143.00000000');foreign=true;await assert.rejects(core.supplierPurchases('2','9',1));foreign=false;late=true;const pending=core.supplierPurchases('2','9',1);while(!finish)await new Promise(r=>setImmediate(r));await core.logout();finish();await assert.rejects(pending);for(const missing of rights){const f=fixture(rights.filter(x=>x!==missing)),c=createDesktopWriteGreenCore({...f.deps,richCards:true});await c.login('normal','secret');await assert.rejects(c.supplierPurchases('2','9',1));}});
test('view-only photo read binds product and session without product card or price request',async()=>{const x=fixture(['product.view']),original=x.deps.fetch;let finish,late=false,wrong=false;const calls=[],core=createDesktopWriteGreenCore({...x.deps,richCards:true,fetch:async(url,opts)=>{calls.push(url);if(url.endsWith('/api/desktop-products/6/photo')){if(late)await new Promise(r=>finish=r);return {ok:true,json:async()=>({success:true,data:{productId:wrong?'7':'6',status:'missing'}})};}return original(url,opts);}});await core.login('normal','secret');assert.deepEqual(await core.readProductPhoto('6'),{productId:'6',status:'missing'});await assert.rejects(core.productCard('6'));assert.equal(calls.some(u=>/\/api\/products\/6$/.test(u)),false);wrong=true;await assert.rejects(core.readProductPhoto('6'));wrong=false;late=true;const waiting=core.readProductPhoto('6');while(!finish)await new Promise(r=>setImmediate(r));await core.logout();finish();await assert.rejects(waiting);});
test('count draft capability uses goods permissions and rejects stale or foreign product replies',async()=>{const rights=['goods.view','goods.create'],x=fixture(rights),original=x.deps.fetch;let late=false,finish,wrong=false;const core=createDesktopWriteGreenCore({...x.deps,richCards:true,fetch:async(url,opts)=>{if(url.endsWith('/api/desktop-runtime'))return{ok:true,json:async()=>({success:true,data:desktopRuntimeInfo({packageSha256:'a'.repeat(64),createdAt:'2026-11-07T12:00:00.000Z',schemaVersion:7})})};if(url.includes('/api/desktop-count/products?')){if(late)await new Promise(r=>finish=r);return{ok:true,json:async()=>({success:true,data:{page:wrong?2:1,hasNext:false,products:[]}})};}return original(url,opts);}});await core.login('normal','secret');const c=await core.countDraft();assert.equal(c.canWrite(),true);assert.deepEqual((await c.products(1,'X')).products,[]);wrong=true;await assert.rejects(c.products(1,'X'));wrong=false;late=true;const waiting=c.products(1,'X');while(!finish)await new Promise(r=>setImmediate(r));await core.logout();finish();await assert.rejects(waiting);});

test('purchase costs require V7 and all three rights, bind product and reject late logout',async()=>{const rights=['product.view','product.edit','purchase.view'],x=fixture(rights),original=x.deps.fetch;let version=6,foreign=false,late=false,finish;const data={productId:'6',status:'none',stockAverageTryExact4:null,lastNetPurchase:null,purchaseWeightedByCurrency:[]};const core=createDesktopWriteGreenCore({...x.deps,richCards:true,fetch:async(url,opts)=>{if(url.endsWith('/api/desktop-runtime'))return {ok:true,json:async()=>({success:true,data:desktopRuntimeInfo({packageSha256:'a'.repeat(64),createdAt:'2026-11-07T12:00:00.000Z',schemaVersion:version})})};if(url.endsWith('/purchase-costs')){if(late)await new Promise(r=>finish=r);return {ok:true,json:async()=>({success:true,data:foreign?{...data,productId:'8'}:data})};}return original(url,opts);}});await core.login('normal','secret');assert.equal(await core.productPurchaseCosts('6'),null);version=7;assert.equal((await core.productPurchaseCosts('6')).status,'none');foreign=true;await assert.rejects(core.productPurchaseCosts('6'));foreign=false;late=true;const pending=core.productPurchaseCosts('6');while(!finish)await new Promise(r=>setImmediate(r));await core.logout();finish();await assert.rejects(pending);for(const missing of rights){const f=fixture(rights.filter(v=>v!==missing)),c=createDesktopWriteGreenCore({...f.deps,richCards:true});await c.login('normal','secret');await assert.rejects(c.productPurchaseCosts('6'));}});

test('preparation barcode uses read-only scoped transport, exact echo and live session',async()=>{const x=fixture(['sales.view','product.view','warehouse.view']),original=x.deps.fetch,calls=[];let wrong=false,late=false,finish;const version='0x0000000000000001';const core=createDesktopWriteGreenCore({...x.deps,richCards:true,fetch:async(url,opts)=>{if(url.endsWith('/api/desktop-runtime'))return {ok:true,json:async()=>({success:true,data:desktopRuntimeInfo({packageSha256:'a'.repeat(64),createdAt:'2026-11-07T12:00:00.000Z',schemaVersion:7})})};if(url.includes('/barcode-check?')){calls.push({url,method:opts.method??'GET'});if(late)await new Promise(r=>finish=r);return {ok:true,json:async()=>({success:true,data:{invoiceId:'15',version,barcode:wrong?'wrong':'000000000092',status:'MATCH',itemIds:['25']}})};}return original(url,opts);}});await core.login('normal','secret');const sale=core.sale(),warehouse=await core.warehouse();assert.equal((await sale.barcodeCheck('15',version,'000000000092')).itemIds[0],'25');assert.equal((await warehouse.barcodeCheck('15',version,'000000000092')).status,'MATCH');assert.equal(calls.length,2);assert.ok(calls.every(c=>c.method==='GET'&&c.url.includes('barcode=000000000092')));wrong=true;await assert.rejects(sale.barcodeCheck('15',version,'000000000092'));wrong=false;late=true;const pending=warehouse.barcodeCheck('15',version,'000000000092');while(!finish)await new Promise(r=>setImmediate(r));await core.logout();finish();await assert.rejects(pending);});
